// The one icon set: every weapon, category, perk, streak, tactical, lethal, mode, map, medal, attachment slot and UI
// action, drawn in one style. Original drawings; nothing traced.
//
// Style rules (keep them when adding an icon):
// - Solid forms, not outlines. Corners are 45 degree chamfers, like the stencil face; anything round is an octagon.
// - Lines, where an icon needs one, are 3 units on the 32 grid with square caps and mitred joins.
// - Detail is cut out of the solid (holes), never drawn on top, so an icon still reads in one flat colour.
// - Two optional tones: `b` (back layer, 45% opacity) for depth, `a` (accent, sodium by default) for the one part
//   that matters: the spark, the lamp, the payload. Set --icon-accent: currentColor on a container for one colour.
// Square icons sit on a 32 grid. Weapons are side-on silhouettes, muzzle right, on a 60x24 strip that is fitted
// automatically, so `icon('ar', {size: 20})` is 20 tall and 50 wide. `{square: true}` gives a weapon fitted to a
// square at an angle, which is also what the category icons are.
//
// API: icon(id, {size, color, accent, square, title, cls}) -> SVG markup string. Unknown ids get a neutral fallback.
//      ICON_IDS lists every id; ITEM_ICONS (id -> inner markup on the 32 grid) is kept for older callers.

import { v10Icons } from './icons-v10.js';
import { mapIcons } from './icons-maps.js';

// ---- Geometry. Polygons are flat [x, y, x, y, ...] arrays. ----------------------------------------------------------

// Chamfered rectangle. `c` is one chamfer for all corners or [tl, tr, br, bl].
function R(x, y, w, h, c = 0) {
  const [a, b, d, e] = Array.isArray(c) ? c : [c, c, c, c];
  return [x + a, y, x + w - b, y, x + w, y + b, x + w, y + h - d, x + w - d, y + h, x + e, y + h, x, y + h - e, x, y + a];
}
const P = (...xy) => xy;
// Octagon with flat sides `r` from the centre: the house circle.
function O(cx, cy, r) {
  const k = r / Math.cos(Math.PI / 8), out = [];
  for (let i = 0; i < 8; i++) { const t = Math.PI / 8 + i * Math.PI / 4; out.push(cx + Math.cos(t) * k, cy + Math.sin(t) * k); }
  return out;
}
// A bar of width w from (x1,y1) to (x2,y2), square ends.
function bar(x1, y1, x2, y2, w) {
  const dx = x2 - x1, dy = y2 - y1, l = Math.hypot(dx, dy) || 1, nx = -dy / l * w / 2, ny = dx / l * w / 2;
  return [x1 + nx, y1 + ny, x2 + nx, y2 + ny, x2 - nx, y2 - ny, x1 - nx, y1 - ny];
}
// Star with n points.
function star(cx, cy, ro, ri, n = 5, rot = -90) {
  const out = [];
  for (let i = 0; i < n * 2; i++) { const t = (rot + i * 180 / n) * Math.PI / 180, r = i % 2 ? ri : ro; out.push(cx + Math.cos(t) * r, cy + Math.sin(t) * r); }
  return out;
}
// Octagonal arc as a polyline, degrees, 0 = east, clockwise on screen.
function arc(cx, cy, r, a0, a1, step = 22.5) {
  const out = [], n = Math.max(1, Math.round(Math.abs(a1 - a0) / step));
  for (let i = 0; i <= n; i++) { const t = (a0 + (a1 - a0) * i / n) * Math.PI / 180; out.push(cx + Math.cos(t) * r, cy + Math.sin(t) * r); }
  return out;
}
function rot(pts, deg, cx = 16, cy = 16) {
  const t = deg * Math.PI / 180, c = Math.cos(t), s = Math.sin(t), out = [];
  for (let i = 0; i < pts.length; i += 2) { const x = pts[i] - cx, y = pts[i + 1] - cy; out.push(cx + x * c - y * s, cy + x * s + y * c); }
  return out;
}
const mapPts = (pts, f) => { const out = []; for (let i = 0; i < pts.length; i += 2) { const [x, y] = f(pts[i], pts[i + 1]); out.push(x, y); } return out; };
const LAYERS = ['f', 'h', 'b', 'bh', 'a', 'ah', 's', 'as'];
// Applies a point transform to every layer of a spec.
function xform(spec, f) {
  const out = { ...spec };
  for (const k of LAYERS) if (spec[k]) out[k] = spec[k].map(p => mapPts(p, f));
  return out;
}
const rotSpec = (spec, deg, cx = 16, cy = 16) => xform(spec, (x, y) => { const p = rot([x, y], deg, cx, cy); return [p[0], p[1]]; });

// ---- Path output ------------------------------------------------------------------------------------------------

const n2 = v => Math.round(v * 100) / 100;
function area(p) { let a = 0; for (let i = 0; i < p.length; i += 2) { const j = (i + 2) % p.length; a += p[i] * p[j + 1] - p[j] * p[i + 1]; } return a; }
function reversePts(p) { const out = []; for (let i = p.length - 2; i >= 0; i -= 2) out.push(p[i], p[i + 1]); return out; }
// Solids wind clockwise and holes anticlockwise, so with the nonzero rule solids merge and holes cut.
function polyD(p, hole) {
  const q = (area(p) > 0) === !hole ? p : reversePts(p);
  let d = `M${n2(q[0])} ${n2(q[1])}`;
  for (let i = 2; i < q.length; i += 2) d += `L${n2(q[i])} ${n2(q[i + 1])}`;
  return d + 'Z';
}
function lineD(p) {
  let d = `M${n2(p[0])} ${n2(p[1])}`;
  for (let i = 2; i < p.length; i += 2) d += `L${n2(p[i])} ${n2(p[i + 1])}`;
  return d;
}
const ACCENT = 'fill:var(--icon-accent,var(--c-sodium,#f2a63b))';
const ACCENT_STROKE = 'stroke:var(--icon-accent,var(--c-sodium,#f2a63b))';
function markup(spec) {
  const sw = spec.sw ?? 3;
  let out = '';
  const solid = (f = [], h = []) => f.map(p => polyD(p, false)).join('') + h.map(p => polyD(p, true)).join('');
  if (spec.b?.length) out += `<path d="${solid(spec.b, spec.bh)}" fill="currentColor" fill-opacity=".45" stroke="none"/>`;
  if (spec.f?.length) out += `<path d="${solid(spec.f, spec.h)}" fill="currentColor" stroke="none"/>`;
  if (spec.s?.length) out += `<path d="${spec.s.map(lineD).join('')}" fill="none" stroke="currentColor" stroke-width="${sw}" stroke-linecap="square" stroke-linejoin="miter"/>`;
  if (spec.a?.length) out += `<path d="${solid(spec.a, spec.ah)}" stroke="none" style="${ACCENT}"/>`;
  if (spec.as?.length) out += `<path d="${spec.as.map(lineD).join('')}" fill="none" stroke-width="${sw}" stroke-linecap="square" stroke-linejoin="miter" style="${ACCENT_STROKE}"/>`;
  return out;
}

// Bounding box of a spec's solids and lines (lines padded by half their width).
function bbox(spec) {
  let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
  for (const k of ['f', 'b', 'a', 's', 'as']) for (const p of spec[k] ?? []) {
    const pad = k === 's' || k === 'as' ? (spec.sw ?? 3) / 2 : 0;
    for (let i = 0; i < p.length; i += 2) { x0 = Math.min(x0, p[i] - pad); x1 = Math.max(x1, p[i] + pad); y0 = Math.min(y0, p[i + 1] - pad); y1 = Math.max(y1, p[i + 1] + pad); }
  }
  return { x0, y0, x1, y1, w: x1 - x0, h: y1 - y0 };
}
// Scales and centres a spec into a box, never enlarging past `maxScale`.
function fit(spec, W, H, pad, maxScale = 9) {
  const b = bbox(spec), s = Math.min((W - pad * 2) / b.w, (H - pad * 2) / b.h, maxScale);
  const ox = (W - b.w * s) / 2 - b.x0 * s, oy = (H - b.h * s) / 2 - b.y0 * s;
  return xform(spec, (x, y) => [x * s + ox, y * s + oy]);
}

