// ---- Square icons on the 32 grid. ------------------------------------------------------------------------------

const gear = (cx, cy, r, hole) => {
  const f = [O(cx, cy, r)];
  for (let k = 0; k < 8; k++) f.push(rot(R(cx - r * .28, cy - r * 1.42, r * .56, r * .6), k * 45, cx, cy));
  return { f, h: [O(cx, cy, hole)] };
};
const chevrons = (ys, w = 24, t = 5, rise = 8) => ys.map(y => P(16 - w / 2, y + rise, 16, y, 16 + w / 2, y + rise, 16 + w / 2, y + rise + t, 16, y + t, 16 - w / 2, y + rise + t));
const tag = (x, y, w, h) => R(x, y, w, h, [w * .28, w * .28, 1.2, 1.2]);
const lamps = (pts, r) => ({ h: pts.map(([x, y]) => O(x, y, r + 1)), a: pts.map(([x, y]) => O(x, y, r)) });
const shield = P(16, 2, 28, 6, 28, 15, 24, 23, 16, 30, 8, 23, 4, 15, 4, 6);
const shieldIn = P(16, 6, 24.5, 8.8, 24.5, 15, 21.5, 21, 16, 25.5, 10.5, 21, 7.5, 15, 7.5, 8.8);
const merge = (...specs) => {
  const out = {};
  for (const s of specs) for (const k of Object.keys(s)) out[k] = Array.isArray(s[k]) ? [...(out[k] ?? []), ...s[k]] : s[k];
  return out;
};

// A weapon silhouette shrunk onto the 32 grid and turned, for icons built from guns.
const mini = (id, deg, mirror = false) => {
  const m = xform(fit(WEAPON_SPECS[id], 32, 12, 0), (x, y) => [mirror ? 32 - x : x, y + 10]);
  return rotSpec(m, deg);
};
