// ---- Build ------------------------------------------------------------------------------------------------------

const W_W = 60, W_H = 24;
const inner = new Map();   // id -> { body, vb, wide }
function build(id) {
  let hit = inner.get(id);
  if (hit) return hit;
  if (WEAPON_SPECS[id]) {
    hit = { body: markup(fit(WEAPON_SPECS[id], W_W, W_H, 0.6, 1.45)), vb: `0 0 ${W_W} ${W_H}`, wide: W_W / W_H };
  } else if (id.startsWith('square:') && WEAPON_SPECS[id.slice(7)]) {
    hit = { body: markup(fit(rotSpec(WEAPON_SPECS[id.slice(7)], -32, 30, 12), 32, 32, 1.5)), vb: '0 0 32 32', wide: 1 };
  } else if (id.startsWith('cat:') && CATEGORY_WEAPON[id.slice(4)]) {
    return build('square:' + CATEGORY_WEAPON[id.slice(4)]);
  } else if (SQUARE[id]) {
    hit = { body: markup(SQUARE[id]), vb: '0 0 32 32', wide: 1 };
  } else {
    return null;
  }
  inner.set(id, hit);
  return hit;
}

// Resolves any reasonable spelling: 'ar', 'cat:SMG', 'SMG', 'medal:double', 'double', 'mode:tdm', 'map:dust', 'back'.
export function resolveIcon(id) {
  if (id == null) return 'unknown';
  id = String(id);
  if (WEAPON_SPECS[id] || SQUARE[id]) return id;
  if (CATEGORY_WEAPON[id]) return 'cat:' + id;
  if (id.startsWith('cat:') && CATEGORY_WEAPON[id.slice(4)]) return id;
  if (id.startsWith('square:') && WEAPON_SPECS[id.slice(7)]) return id;
  if (ALIAS[id]) return ALIAS[id];
  if (SQUARE['ui:' + id]) return 'ui:' + id;
  return 'unknown';
}

// Full markup for a name, or null when the set has no drawing for it (callers keep their own fallback).
export function uiIcon(name, opts) {
  const key = resolveIcon(name);
  return key === 'unknown' && name !== 'unknown' ? null : icon(key, opts);
}

export const hasIcon = id => resolveIcon(id) !== 'unknown' || id === 'unknown';

// Markup for an icon. size is the height in px (a weapon is 2.5x as wide). color sets currentColor; accent sets
// the accent tone (pass 'currentColor' for a one-colour icon). Decorative unless a title is given.
export function icon(id, { size = 24, color, accent, square = false, title, cls = '' } = {}) {
  const key = resolveIcon(id);
  const b = build(square && WEAPON_SPECS[key] ? 'square:' + key : key) ?? build('unknown');
  const w = Math.round(size * b.wide * 100) / 100;
  let style = '';
  if (color) style += `color:${color};`;
  if (accent) style += `--icon-accent:${accent};`;
  const a11y = title ? `role="img" aria-label="${String(title).replace(/"/g, '&quot;')}"` : 'aria-hidden="true"';
  return `<svg class="ico ico-${key.replace(/[^a-z0-9_-]/gi, '-')}${cls ? ' ' + cls : ''}" viewBox="${b.vb}" width="${w}" height="${size}"${style ? ` style="${style}"` : ''} ${a11y} focusable="false">${b.body}</svg>`;
}

// Every id with a drawing, grouped, for the gallery and for tests.
export const ICON_GROUPS = {
  weapons: Object.keys(WEAPON_SPECS),
  categories: Object.keys(CATEGORY_WEAPON).map(c => 'cat:' + c),
  streaks: ['uav', 'jammer', 'resupply', 'turret', 'mortar', 'strike', 'overwatch', 'chopper', 'emp', 'gunship', 'missile', 'swarm', 'juggernaut',
    'sweep', 'recon', 'airdrop', 'plates', 'hound', 'dome', 'bombrun', 'rover', 'blackbird', 'vulture'],
  tacticals: ['smoke', 'flash', 'stim', 'decoy', 'sensor', 'trophy', 'stun', 'gas', 'shock', 'snapshot', 'blackout', 'bulwark', 'tagger', 'medpack'],
  lethals: ['frag', 'sticky', 'molotov', 'mine', 'cluster', 'hatchet', 'impact', 'claymore', 'drill', 'charge', 'thermite', 'tripwire', 'crawler', 'shiv'],
  objectives: ['bomb'],
  perks: ['marathon', 'flak', 'quickmend', 'tacmask', 'adrenaline', 'scavenger', 'fasthands', 'strongarm', 'bandolier', 'hardline', 'ghost', 'coldblood', 'deadsilence', 'tracker', 'engineer', 'hardtarget'],
  slots: ['optic', 'barrel', 'mag', 'grip'],
  modes: Object.keys(SQUARE).filter(k => k.startsWith('mode:')),
  maps: Object.keys(SQUARE).filter(k => k.startsWith('map:')),
  medals: Object.keys(SQUARE).filter(k => k.startsWith('medal:')),
  ui: [...Object.keys(SQUARE).filter(k => k.startsWith('ui:')), 'slide', 'swap', 'unknown'],
};
export const ICON_IDS = Object.values(ICON_GROUPS).flat();

// Older callers wrap these in their own <svg viewBox="0 0 32 32">. Square ids only, plus legacy bare names.
export const ITEM_ICONS = new Proxy({}, {
  get(_, id) {
    if (typeof id !== 'string') return undefined;
    const key = resolveIcon(id);
    if (key === 'unknown' || WEAPON_SPECS[key]) return undefined;
    return build(key)?.body;
  },
  has(_, id) { const k = resolveIcon(id); return k !== 'unknown' && !WEAPON_SPECS[k]; },
});

// V9 streak icons: an open polyline along a circular arc (degrees, SVG y down), and a polygon turned about a point.
function arcPts(cx, cy, r, a0, a1, n) {
  const out = [];
  for (let i = 0; i <= n; i++) { const a = (a0 + (a1 - a0) * i / n) * Math.PI / 180; out.push(cx + Math.cos(a) * r, cy + Math.sin(a) * r); }
  return out;
}
function rotPts(pts, cx, cy, deg) {
  const a = deg * Math.PI / 180, c = Math.cos(a), sn = Math.sin(a), out = [];
  for (let i = 0; i < pts.length; i += 2) { const x = pts[i] - cx, y = pts[i + 1] - cy; out.push(cx + x * c - y * sn, cy + x * sn + y * c); }
  return out;
}
